mapper.select:
SELECT p.post_id, p.user_id, u.nickname, p.cert_id, p.category, p.title, p.view_count, p.created_at FROM posts p LEFT JOIN users u ON p.user_id = u.user_id
(p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE posts
SET category = #{category},
    title    = #{title},
    content  = #{content}
WHERE post_id = #{postId}

UPDATE posts
SET view_count = view_count + 1
WHERE post_id = #{postId}
